={
  "model": "openai/gpt-oss-120b",
  "messages": [
    {
      "role": "system",
      "content": "You extract hostel resident records from a warden's WhatsApp message (text or voice transcript). Messages can be phrased naturally in many ways — do not expect fixed templates. Pay special attention to room numbers: whenever the message explicitly mentions a room in forms such as 'room 101', 'Room no 101', 'room number 101', 'in room 101', or similar wording, extract the numeric room value as the room string (for example, '101'). Do not leave room null when a room number is explicitly present. For CNIC, whenever the message explicitly provides a CNIC/NIC number, extract it as a string and preserve its digits and hyphens; accept forms such as 'CNIC 35202-1234567-1' or 'NIC 3520212345671'. Do not invent or infer a CNIC. Return ONLY valid JSON, no markdown, no explanation, with exactly these fields: action (one of: new, update, vacate, query), name (string or null), cnic (string or null), room (string or null), fee (string or null), rent_status (one of: Paid, Pending, or null), contact_number (string or null), address (string or null), notes (string or null), query_type (one of: resident_lookup, unpaid_list, total_income, or null — only set when action is query), requested_field (one of: rent, rent_status, contact_number, room, address, cnic, all, or null — only set when query_type is resident_lookup). Rules: Only include a value for a field if it is clearly and explicitly mentioned in the message. Use null for anything not mentioned — never guess, assume, or invent a value, and never use the sender's own phone number as contact_number unless they explicitly stated a number in the message. For action new, name and room are the minimum needed — fee, contact_number, and address are optional, include only if explicitly mentioned. For action update, only the field(s) actually mentioned should be set to a value — every other field must be null, since null means do not change this field. name and room together identify which resident is being referenced for update or vacate; if only a name is given, still extract it as best effort. Examples: 'new student Ahmed room 101 CNIC 35202-1234567-1 rent 15000' means action new, name Ahmed, room 101, cnic 35202-1234567-1, fee 15000, everything else null. 'Add Ahmed to room 101, CNIC 35202-1234567-1, rent 15000, contact 03001234567, address Islamabad' means action new with cnic, contact_number and address also set. 'Change Ahmed's rent to 20000' means action update, name Ahmed, fee 20000, all other fields null. 'Ahmed paid rent' or 'mark Ahmed as paid' means action update, rent_status Paid, all other fields null; if a room is explicitly mentioned, extract it, e.g. 'Mark Ahmed Khan in room 101 as paid' means name Ahmed Khan, room 101, rent_status Paid. 'Update Ahmed's contact number to 03111234567' means action update, contact_number set, all other fields null. 'Zara room 9 left' means action vacate. 'tell me Ali Raza's info' means query_type resident_lookup, requested_field all. 'what's Ali Raza's rent' means query_type resident_lookup, requested_field rent. 'What is Ali Raza's CNIC?' means query_type resident_lookup, requested_field cnic. 'who hasn't paid rent' means query_type unpaid_list. 'total income' means query_type total_income."
    },
    {
      "role": "user",
      "content": "{{ JSON.stringify($json.messageText).slice(1, -1) }}"
    }
  ]
}

parameters.jsCode:
const raw = $input.first().json.choices[0].message.content;
const cleaned = raw.replace(/```json|```/g, '').trim();
let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (e) {
  parsed = { action: 'unknown', name: null, cnic: null, room: null, fee: null, rent_status: null, contact_number: null, address: null, notes: 'PARSE_ERROR', query_type: null, requested_field: null };
}

function normalizeRoom(value) {
  if (value === null || value === undefined || value === '') return null;
  const text = String(value).trim();
  const numericRoom = text.match(/\b\d+\b/);
  return numericRoom ? numericRoom[0] : text;
}

function normalizeName(value) {
  if (value === null || value === undefined || value === '') return null;
  return String(value).trim().replace(/\s+/g, ' ');
}

parsed.name = normalizeName(parsed.name);
parsed.cnic = parsed.cnic ? String(parsed.cnic).trim().replace(/\D/g, '') : null;
parsed.room = normalizeRoom(parsed.room);
parsed.residentKey = parsed.name && parsed.room ? `${parsed.name}|${parsed.room}` : '';

let senderPhone = null;
try { senderPhone = $('Edit Fields2').first().json.senderPhone; } catch (e) {}
if (!senderPhone) {
  try { senderPhone = $('Edit Fields').first().json.senderPhone; } catch (e) {}
}
parsed.senderPhone = senderPhone;

return [{ json: parsed }];

const c = $('Code in JavaScript').item.json;
let msg;
if (c.action === 'new') {
  const feeText = c.fee ? `, Rs ${c.fee}/mo` : '';
  msg = `✅ Added: ${c.name}, Room ${c.room}${feeText}${c.cnic ? `, CNIC ${c.cnic}` : ''}`;
} else if (c.action === 'update') {
  msg = `✅ Updated: ${c.name}, Room ${c.room}`;
} else if (c.action === 'vacate') {
  msg = `🚪 Marked vacated: ${c.name}, Room ${c.room}`;
} else {
  msg = 'Saved.';
}
return [{ json: { replyMessage: msg, senderPhone: c.senderPhone } }];

const extracted = $('Code in JavaScript').item.json;
const rows = $input.all();

function normalizeRoom(value) {
  if (value === null || value === undefined || value === '') return null;
  const text = String(value).trim();
  const numericRoom = text.match(/\b\d+\b/);
  return numericRoom ? numericRoom[0] : text;
}

function normalizeName(value) {
  if (value === null || value === undefined || value === '') return null;
  return String(value).trim().replace(/\s+/g, ' ').toLowerCase();
}

const targetName = normalizeName(extracted.name);
const targetRoom = normalizeRoom(extracted.room);

// Get Resident Row searches by name. Here we select the row whose room matches
// after normalization, so values like "Room 102" or the typo "Rome 102"
// still match an incoming room value of "102".
const existing = rows
  .map(item => item.json)
  .find(row => normalizeName(row['Name']) === targetName && normalizeRoom(row['Room no.']) === targetRoom);

if (!existing) {
  return [{ json: { notFound: true, name: extracted.name, room: extracted.room, action: extracted.action, senderPhone: extracted.senderPhone } }];
}

function pick(newVal, oldVal, fallback) {
  if (newVal !== null && newVal !== undefined && newVal !== '') return newVal;
  if (oldVal !== undefined && oldVal !== null && oldVal !== '') return oldVal;
  return fallback;
}

const canonicalName = pick(extracted.name, existing['Name'], extracted.name);
const canonicalRoom = normalizeRoom(pick(extracted.room, existing['Room no.'], extracted.room));

const merged = {
  notFound: false,
  senderPhone: extracted.senderPhone,
  // Always write the canonical key so a legacy/malformed ResidentKey is repaired.
  residentKey: canonicalName && canonicalRoom ? `${canonicalName}|${canonicalRoom}` : extracted.residentKey,
  name: canonicalName,
  room: canonicalRoom,
  cnic: pick(extracted.cnic, existing['CNIC'], ''),
  contact_number: pick(extracted.contact_number, existing['Contact no.'], ''),
  fee: pick(extracted.fee, existing['Room Rent'], ''),
  rent_status: pick(extracted.rent_status, existing['Rent Status'], 'Pending'),
  address: pick(extracted.address, existing['Personal Address'], ''),
  personStatus: existing["Person's Status"] || 'Active'
};

if (extracted.action === 'vacate') {
  merged.personStatus = 'Vacated';
}

return [{ json: merged }];

const p = $input.first().json;
let error = null;
const validActions = ['new', 'update', 'vacate', 'query'];
const validQueryTypes = ['resident_lookup', 'unpaid_list', 'total_income'];

if (p.notes === 'PARSE_ERROR' || !validActions.includes(p.action)) {
  error = "Sorry, I couldn't understand that message. Try something like:\n• 'new student Ahmed room 101 rent 15000'\n• 'update Ahmed room 101 rent to 15000'\n• 'Ahmed room 101 left'";
} else if (p.action === 'new' && (!p.name || !p.room)) {
  error = "To add a new resident I need both a name and room number, e.g. 'new student Ahmed room 101 rent 15000'.";
} else if (p.cnic && !/^\d{13}$/.test(String(p.cnic))) {
  error = "The CNIC should contain 13 digits. You can send it with or without dashes, for example 35202-1234567-1.";
} else if ((p.action === 'update' || p.action === 'vacate') && (!p.name || !p.room)) {
  const missing = [];
  if (!p.name) missing.push('name');
  if (!p.room) missing.push('room number');
  error = `I need the resident's ${missing.join(' and ')} to do that. Try: 'update Ahmed room 101 rent to 15000'.`;
} else if (p.action === 'query') {
  if (!validQueryTypes.includes(p.query_type)) {
    error = "I couldn't identify the lookup or report you want. Try: 'What room is Ahmed Khan in?', 'Who hasn't paid rent?', or 'What is the total rent income?'";
  } else if (p.query_type === 'resident_lookup' && !p.name) {
    error = "I need the resident's name for that lookup. Try: 'What room is Ahmed Khan in?'";
  }
}

return [{ json: { ...p, validationError: error } }];

const c = $input.first().json;
const msg = `⚠️ I couldn't find a resident named "${c.name || '?'}" in room ${c.room || '?'}. If this is a new resident, try: 'new student ${c.name || 'Name'} room ${c.room || '101'} rent 15000'. If they should already exist, please double check the spelling of the name and room.`;
return [{ json: { replyMessage: msg, senderPhone: c.senderPhone } }];

const query = $('Code in JavaScript').item.json;
const rows = $input.all().map(item => item.json || {});

function norm(value) {
  return String(value ?? '').trim().replace(/\s+/g, ' ').toLowerCase();
}

function room(value) {
  const text = String(value ?? '').trim();
  const m = text.match(/\b\d+\b/);
  return m ? m[0] : text;
}

function money(value) {
  const n = Number(String(value ?? '').replace(/[^0-9.\-]/g, ''));
  return Number.isFinite(n) ? n : 0;
}

const activeRows = rows.filter(r => norm(r["Person's Status"]) !== 'vacated');
let reply;

if (query.query_type === 'resident_lookup') {
  const target = norm(query.name);
  const matches = rows.filter(r => norm(r['Name']) === target);

  if (!matches.length) {
    reply = `⚠️ I couldn't find a resident named "${query.name || '?'}" in the hostel records.`;
  } else if (matches.length > 1) {
    const list = matches.map(r => {
      const n = r['Name'] || query.name;
      const rm = room(r['Room no.']) || '?';
      const cnic = r['CNIC'] || '?';
      const rent = r['Room Rent'] || '?';
      const status = r['Rent Status'] || '?';
      return `${n} — Room ${rm}, CNIC ${cnic}, Rent Rs ${rent}, Status ${status}`;
    }).join('\n');
    reply = `I found multiple records for ${query.name}:\n${list}\nPlease include the room number if you want a specific record.`;
  } else {
    const r = matches[0];
    const requested = query.requested_field || 'all';
    const name = r['Name'] || query.name;
    const rm = room(r['Room no.']) || '?';

    if (requested === 'room') {
      reply = `${name} is in Room ${rm}.`;
    } else if (requested === 'rent') {
      reply = `${name}'s rent is Rs ${r['Room Rent'] || 0}/month.`;
    } else if (requested === 'rent_status') {
      reply = `${name}'s rent status is ${r['Rent Status'] || 'Unknown'}.`;
    } else if (requested === 'contact_number') {
      reply = `${name}'s contact number is ${r['Contact no.'] || 'not recorded'}.`;
    } else if (requested === 'address') {
      reply = `${name}'s address is ${r['Personal Address'] || 'not recorded'}.`;
    } else if (requested === 'cnic') {
      reply = `${name}'s CNIC is ${r['CNIC'] || 'not recorded'}.`;
    } else {
      reply = `📋 ${name}\nRoom: ${rm}\nCNIC: ${r['CNIC'] || 'not recorded'}\nRent: Rs ${r['Room Rent'] || 0}/month\nRent status: ${r['Rent Status'] || 'Unknown'}\nContact: ${r['Contact no.'] || 'not recorded'}\nAddress: ${r['Personal Address'] || 'not recorded'}\nStatus: ${r["Person's Status"] || 'Active'}`;
    }
  }
} else if (query.query_type === 'unpaid_list') {
  const unpaid = activeRows.filter(r => norm(r['Rent Status']) !== 'paid');
  if (!unpaid.length) {
    reply = '✅ All active residents have paid their rent.';
  } else {
    const lines = unpaid.map((r, i) => `${i + 1}. ${r['Name'] || 'Unknown'} — Room ${room(r['Room no.']) || '?'} — Rs ${r['Room Rent'] || 0}`);
    reply = `💰 Residents with unpaid/pending rent (${unpaid.length}):\n${lines.join('\n')}`;
  }
} else if (query.query_type === 'total_income') {
  const total = activeRows.reduce((sum, r) => sum + money(r['Room Rent']), 0);
  reply = `💰 Total monthly rent income from active residents: Rs ${total.toLocaleString('en-PK')}.`;
} else {
  reply = "I couldn't determine which report you want.";
}

return [{ json: { replyMessage: reply, senderPhone: query.senderPhone } }];

const incoming = $('Code in JavaScript').item.json;
const rows = $input.all().map(i => i.json);
function norm(value) { return value === null || value === undefined ? '' : String(value).trim().toLowerCase(); }
function room(value) { const text = norm(value); const m = text.match(/\b\d+\b/); return m ? m[0] : text; }
function isActive(value) { const s = norm(value); return s === '' || ['active','occupied','current'].includes(s); }
const targetRoom = room(incoming.room);
const targetCnic = norm(incoming.cnic);
const activeRoomConflict = rows.find(r => room(r['Room no.']) === targetRoom && isActive(r["Person's Status"]));
const cnicConflict = targetCnic ? rows.find(r => norm(r['CNIC']) === targetCnic) : null;
let conflictType = null, conflictRow = null;
if (activeRoomConflict) { conflictType = 'room'; conflictRow = activeRoomConflict; } else if (cnicConflict) { conflictType = 'cnic'; conflictRow = cnicConflict; }
return [{ json: { ...incoming, canCreate: !conflictType, conflictType, conflictName: conflictRow ? (conflictRow['Name'] || '') : '', conflictRoom: conflictRow ? (conflictRow['Room no.'] || '') : '', conflictCnic: conflictRow ? (conflictRow['CNIC'] || '') : '' } }];

const c = $input.first().json;
let msg;
if (c.conflictType === 'room') msg = `⚠️ Room ${c.room} is already occupied by ${c.conflictName || 'another resident'}. I did not add ${c.name}. Please choose an available room.`;
else if (c.conflictType === 'cnic') msg = `⚠️ This CNIC is already registered${c.conflictName ? ` to ${c.conflictName}` : ''}${c.conflictRoom ? ` in room ${c.conflictRoom}` : ''}. I did not create a duplicate resident.`;
else msg = '⚠️ I could not add the resident because the request conflicts with existing resident data.';
return [{ json: { replyMessage: msg, senderPhone: c.senderPhone } }];
